// A 2x2 matrix stored row-major: [[a, b], [c, d]]
pub struct Matrix2x2 {
    pub data: [[f64; 2]; 2],
}

impl Matrix2x2 {
    pub fn new(a: f64, b: f64, c: f64, d: f64) -> Self {
        Matrix2x2 { data: [[a, b], [c, d]] }
    }

    // BUG: wrong sign — should be a*d - b*c, not a*d + b*c
    pub fn det(&self) -> f64 {
        let [[a, b], [c, d]] = self.data;
        a * d + b * c
    }

    // BUG: swaps [0][0] with [1][1] instead of [0][1] with [1][0]
    pub fn transpose(&self) -> Matrix2x2 {
        let [[a, b], [c, d]] = self.data;
        Matrix2x2::new(d, b, c, a)
    }

    // BUG: top-right element uses a*b instead of a*d (wrong column)
    pub fn multiply(&self, other: &Matrix2x2) -> Matrix2x2 {
        let [[a, b], [c, d]] = self.data;
        let [[e, f], [g, h]] = other.data;
        Matrix2x2::new(
            a * e + b * g,
            a * b + b * h,  // BUG: should be a*f + b*h
            c * e + d * g,
            c * f + d * h,
        )
    }
}

use matrix2x2::Matrix2x2;

#[test]
fn test_det() {
    let m = Matrix2x2::new(1.0, 2.0, 3.0, 4.0);
    assert!((m.det() - (-2.0)).abs() < 1e-9);
}

#[test]
fn test_det_identity() {
    let m = Matrix2x2::new(1.0, 0.0, 0.0, 1.0);
    assert!((m.det() - 1.0).abs() < 1e-9);
}

#[test]
fn test_transpose() {
    let m = Matrix2x2::new(1.0, 2.0, 3.0, 4.0);
    let t = m.transpose();
    // transpose of [[1,2],[3,4]] is [[1,3],[2,4]]
    assert_eq!(t.data[0][0], 1.0);
    assert_eq!(t.data[0][1], 3.0);
    assert_eq!(t.data[1][0], 2.0);
    assert_eq!(t.data[1][1], 4.0);
}

#[test]
fn test_multiply_identity() {
    let m = Matrix2x2::new(1.0, 2.0, 3.0, 4.0);
    let id = Matrix2x2::new(1.0, 0.0, 0.0, 1.0);
    let result = m.multiply(&id);
    assert_eq!(result.data[0][0], 1.0);
    assert_eq!(result.data[0][1], 2.0);
    assert_eq!(result.data[1][0], 3.0);
    assert_eq!(result.data[1][1], 4.0);
}

#[test]
fn test_multiply_general() {
    // [[1,2],[3,4]] * [[5,6],[7,8]] = [[19,22],[43,50]]
    let a = Matrix2x2::new(1.0, 2.0, 3.0, 4.0);
    let b = Matrix2x2::new(5.0, 6.0, 7.0, 8.0);
    let c = a.multiply(&b);
    assert!((c.data[0][0] - 19.0).abs() < 1e-9);
    assert!((c.data[0][1] - 22.0).abs() < 1e-9);
    assert!((c.data[1][0] - 43.0).abs() < 1e-9);
    assert!((c.data[1][1] - 50.0).abs() < 1e-9);
}
